def can_construct_city(L, R):
    if R - L + 1 > 31:
        return False

    n = R - L + 2
    m = n - 1
    roads = []

    for i in range(1, n):
        roads.append((i, i + 1, L + i - 1))

    return n, m, roads

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    L = int(data[0])
    R = int(data[1])

    if not can_construct_city(L, R):
        print("NO")
    else:
        n, m, roads = can_construct_city(L, R)
        print("YES")
        print(n, m)
        for a, b, c in roads:
            print(a, b, c)

if __name__ == "__main__":
    main()
